CREATE POLICY public_read_published_property_features ON public.property_features AS PERMISSIVE FOR SELECT TO anon, authenticated USING ((EXISTS (SELECT 1 FROM properties p WHERE ((p.id = property_features.property_id) AND (p.status = 'published'::text) AND (p.deleted_at IS NULL)))));
CREATE POLICY team_manage_property_features ON public.property_features AS PERMISSIVE FOR ALL TO authenticated USING (has_permission('properties.manage'::text)) WITH CHECK (has_permission('properties.manage'::text));
